<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Havale bildirimleri</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f7f4;color:#26332b;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1180px;margin:30px auto;padding:0 16px}.head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.muted{color:#718077;font-size:13px;line-height:1.6}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.tabs a{padding:9px 13px;border:1px solid #dfe8e1;border-radius:20px;background:#fff;color:#365746;text-decoration:none;font-size:13px}.tabs a.active{background:#176b50;border-color:#176b50;color:#fff}.report{background:#fff;border:1px solid #e4ebe5;border-radius:15px;padding:18px;margin:12px 0;display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr) minmax(220px,1fr);gap:16px;align-items:start}.report h2{font-size:17px;margin:0 0 7px}.amount{font-size:20px;font-weight:850;color:#176b50}.tag{display:inline-block;padding:5px 9px;border-radius:20px;background:#edf5ef;font-size:12px;font-weight:750}.tag.rejected{background:#fff0ed;color:#8b3325}.tag.approved{background:#eaf5ed;color:#176b50}.tag.pending{background:#fff6e7;color:#76551c}.details{overflow-wrap:anywhere;font-size:13px;line-height:1.7}.actions textarea{width:100%;min-height:76px;resize:vertical;padding:10px;border:1px solid #dfe6e0;border-radius:9px;font:inherit}.actions button{min-height:42px;padding:10px 14px;border:0;border-radius:9px;background:#176b50;color:#fff;font:inherit;font-weight:800;cursor:pointer}.actions button.reject{background:#8b3325}.action-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}.empty{background:#fff;border:1px solid #e4ebe5;border-radius:14px;padding:28px;text-align:center}@media(max-width:850px){.report{grid-template-columns:1fr;gap:12px}}@media(max-width:520px){.wrap{margin:20px auto}.report{padding:15px}.action-row{display:grid;grid-template-columns:1fr 1fr}.action-row button{width:100%}}
</style></head><body><main class="wrap"><header class="head"><div><h1>Havale / EFT bildirimleri</h1><p class="muted">Müşterilerin gönderdiği transfer bilgilerini inceleyin. Onay, ödemeyi kaydeder ve bekleyen rezervasyonu müsaitlik kontrolünden sonra onaylar.</p></div><a href="<?= e(app_url('/admin')) ?>">← Yönetim paneli</a></header>
<nav class="tabs"><?php foreach(['pending'=>'Bekleyenler','approved'=>'Onaylananlar','rejected'=>'Reddedilenler','all'=>'Tümü'] as $key=>$label): ?><a class="<?= ($reportFilter??'pending')===$key?'active':'' ?>" href="<?= e(app_url('/admin/payments/manual?status='.rawurlencode($key))) ?>"><?= e($label) ?><?php if($key==='pending'): ?> (<?= (int)($pendingReportCount??0) ?>)<?php endif; ?></a><?php endforeach; ?></nav>
<?php foreach(($manualPaymentReports??[]) as $report): ?><article class="report"><section><h2><?= e($report['property_title']) ?></h2><div class="muted">Rezervasyon: <strong><?= e($report['booking_code']) ?></strong></div><div class="muted"><?= e($report['guest_name']) ?> · <?= e($report['guest_email']) ?></div><div class="muted"><?= e(date('d.m.Y H:i',strtotime($report['submitted_at']))) ?></div><p><span class="tag <?= e($report['status']) ?>"><?= e(['pending'=>'İnceleme bekliyor','approved'=>'Onaylandı','rejected'=>'Reddedildi'][$report['status']]??$report['status']) ?></span></p></section>
<section class="details"><div class="amount"><?= e(number_format((float)$report['amount'],2,',','.')) ?> <?= e($report['currency']) ?></div><div><strong>Gönderen:</strong> <?= e($report['sender_name']) ?></div><div><strong>Banka:</strong> <?= e($report['sender_bank']?:'Belirtilmedi') ?></div><div><strong>Transfer referansı:</strong> <?= e($report['transfer_reference']) ?></div><?php if(!empty($report['note'])): ?><div><strong>Açıklama:</strong> <?= e($report['note']) ?></div><?php endif; ?><?php if(!empty($report['review_note'])): ?><div><strong>İşlem notu:</strong> <?= e($report['review_note']) ?></div><?php endif; ?></section>
<?php if($report['status']==='pending'): ?><section class="actions"><form method="post" action="<?= e(app_url('/admin/payments/manual/review')) ?>"><?= csrf_field() ?><input type="hidden" name="report_id" value="<?= (int)$report['id'] ?>"><label class="muted" for="review-note-<?= (int)$report['id'] ?>">Yönetici notu (isteğe bağlı)</label><textarea id="review-note-<?= (int)$report['id'] ?>" name="review_note" maxlength="1000" placeholder="Dekont / banka kontrol notu"></textarea><div class="action-row"><button type="submit" name="decision" value="approved">Ödemeyi onayla</button><button class="reject" type="submit" name="decision" value="rejected">Bildirimi reddet</button></div></form></section><?php else: ?><section class="details"><div><strong>İşlemi yapan:</strong> <?= e($report['reviewer_name']??'Yönetici') ?></div><div><strong>İşlem zamanı:</strong> <?= e($report['reviewed_at']?date('d.m.Y H:i',strtotime($report['reviewed_at'])):'—') ?></div></section><?php endif; ?></article><?php endforeach; ?>
<?php if(empty($manualPaymentReports)): ?><div class="empty">Bu filtrede havale bildirimi bulunmuyor.</div><?php endif; ?>
<section class="report" aria-label="Yeni banka iadesi"><div><h2>Yeni banka iadesi talebi</h2><p class="muted">Yalnızca tahsil edilmiş manuel havaleler. Ödeme işlem numarası ve tutarı girin. Bu işlem banka transferini gerçekleştirmez.</p></div><form class="actions" method="post" action="<?= e(app_url('/admin/payments/manual/refunds/create')) ?>"><?= csrf_field() ?><label for="bank-payment-id">Ödeme işlem numarası</label><input id="bank-payment-id" name="payment_id" type="number" min="1" required style="width:100%;padding:10px;margin:6px 0 12px"><label for="bank-refund-amount">İade tutarı</label><input id="bank-refund-amount" name="amount" type="number" min="0.01" step="0.01" required style="width:100%;padding:10px;margin:6px 0 12px"><label for="bank-refund-reason">İade gerekçesi</label><textarea id="bank-refund-reason" name="reason" maxlength="500"></textarea><button type="submit">İade talebi oluştur</button></form></section>
<section aria-label="Banka iadeleri"><h2>Banka iadesi kayıtları</h2><p class="muted">Bu kayıtlar banka iadesinin takip durumunu gösterir. Banka dekontu doğrulanmadan ödeme tamamlandı kabul edilmez.</p>
<?php foreach(($bankRefunds??[]) as $refund): ?><article class="report"><section><h2><?= e($refund['property_title']) ?></h2><div class="muted">Rezervasyon: <?= e($refund['booking_code']) ?></div><div class="muted"><?= e(date('d.m.Y H:i',strtotime($refund['created_at']))) ?></div></section><section class="details"><div class="amount"><?= e(number_format((float)$refund['amount'],2,',','.')) ?> <?= e($refund['currency']) ?></div><div><strong>Durum:</strong> <?= e(['pending'=>'Beklemede','processing'=>'İşleniyor','succeeded'=>'Tamamlandı','failed'=>'Başarısız','cancelled'=>'İptal'][$refund['status']]??$refund['status']) ?></div><div><strong>Banka referansı:</strong> <?= e($refund['bank_reference']??'—') ?></div></section><section class="details"><div><strong>Gerekçe:</strong> <?= e($refund['reason']??'—') ?></div><div><strong>İnceleyen:</strong> <?= e($refund['reviewer_name']) ?></div><div><strong>Tamamlanma:</strong> <?= e($refund['completed_at']?date('d.m.Y H:i',strtotime($refund['completed_at'])):'—') ?></div></section><?php if(in_array($refund['status'],['pending','processing'],true)): ?><section class="actions"><form method="post" action="<?= e(app_url('/admin/payments/manual/refunds/review')) ?>"><?= csrf_field() ?><input type="hidden" name="refund_id" value="<?= (int)$refund['id'] ?>"><label for="refund-ref-<?= (int)$refund['id'] ?>">Banka referansı (isteğe bağlı)</label><input id="refund-ref-<?= (int)$refund['id'] ?>" name="bank_reference" maxlength="190" value="<?= e($refund['bank_reference']??'') ?>" style="width:100%;padding:10px;margin:6px 0 12px"><div class="action-row"><?php if($refund['status']==='pending'): ?><button type="submit" name="decision" value="processing">İşleme al</button><?php endif; ?><button class="reject" type="submit" name="decision" value="failed">Başarısız</button><button type="submit" name="decision" value="cancelled">İptal et</button></div></form></section><?php endif; ?></article><?php endforeach; ?>
<?php if(empty($bankRefunds)): ?><div class="empty">Henüz banka iadesi kaydı bulunmuyor.</div><?php endif; ?></section>
</main></body></html>